// Emit one item per ad account so the splitInBatches loop processes one account per iteration.
const accounts = [
  'act_10201019819851931',
  'act_708812601077037',
  'act_293603336988341',
  'act_3684421665103341',
  'act_249137098153238',
  'act_1738224836936889',
  'act_1093083055897528'
];
const cfg = $('Config (toggle dry_run)').first().json;
return accounts.map(a => ({ json: { account_id: a, graph_api: cfg.graph_api } }));

// Inside the loop iteration: all pages here belong to the current account.
// Flatten + classify and emit one item per audience.
const accountId = $('Loop Over Accounts').item.json.account_id;
const pages = $input.all();

function classify(t) {
  if (!t || typeof t !== 'object') return 'unknown';
  const geo = t.geo_locations || {};
  const hasCustomLocs = Array.isArray(geo.custom_locations) && geo.custom_locations.length > 0;
  if (hasCustomLocs) return 'drive_time';
  if (Array.isArray(t.custom_audiences) && t.custom_audiences.length > 0) return 'lookalike_or_custom';
  const hasGeo = (Array.isArray(geo.cities) && geo.cities.length) ||
                 (Array.isArray(geo.zips) && geo.zips.length) ||
                 (Array.isArray(geo.countries) && geo.countries.length) ||
                 (Array.isArray(geo.regions) && geo.regions.length);
  if (hasGeo) return 'legacy_geo';
  const hasInterest = (Array.isArray(t.interests) && t.interests.length) ||
                      (Array.isArray(t.behaviors) && t.behaviors.length) ||
                      (Array.isArray(t.flexible_spec) && t.flexible_spec.length);
  if (hasInterest) return 'interest';
  return 'unknown';
}

function extractData(item) {
  const j = item.json;
  if (Array.isArray(j)) return j;
  if (Array.isArray(j.data)) return j.data;
  if (Array.isArray(j.body?.data)) return j.body.data;
  return [];
}

const rows = [];
for (const page of pages) {
  for (const a of extractData(page)) {
    const t = a.targeting || {};
    const geo = t.geo_locations || {};
    const excludedGeo = t.excluded_geo_locations || {};
    const customLocs = Array.isArray(geo.custom_locations) ? geo.custom_locations : [];
    const excludedCustomLocs = Array.isArray(excludedGeo.custom_locations) ? excludedGeo.custom_locations : [];
    const excludedCities = Array.isArray(excludedGeo.cities) ? excludedGeo.cities : [];
    const excludedZips = Array.isArray(excludedGeo.zips) ? excludedGeo.zips : [];
    const excludedAny = excludedCustomLocs.length + excludedCities.length + excludedZips.length;
    rows.push({
      account_id: accountId,
      audience_id: a.id,
      name: a.name || null,
      description: a.description || null,
      kind: classify(t),
      has_custom_locations: customLocs.length > 0,
      has_excluded_geo: excludedAny > 0,
      custom_location_count: customLocs.length,
      excluded_location_count: excludedAny,
      cities: Array.isArray(geo.cities) ? geo.cities.map(c => c.name || c.key || String(c)) : [],
      zips: Array.isArray(geo.zips) ? geo.zips.map(z => z.name || z.key || String(z)) : [],
      countries: Array.isArray(geo.countries) ? geo.countries : [],
      age_min: t.age_min ?? null,
      age_max: t.age_max ?? null,
      approximate_count_lower: a.approximate_count_lower_bound ?? null,
      approximate_count_upper: a.approximate_count_upper_bound ?? null,
      targeting: t,
      time_created: a.time_created || null,
      time_updated: a.time_updated || null
    });
  }
}

return rows.map(r => ({ json: r }));

// Append rows from this iteration into a workflow-static collector
const incoming = $input.all().map(i => i.json);
const staticData = $getWorkflowStaticData('global');
staticData.rows = (staticData.rows || []).concat(incoming);
return [{ json: { iteration_rows: incoming.length, total_so_far: staticData.rows.length } }];

// After loop completes, drain the static-data collector and emit one item per row
const staticData = $getWorkflowStaticData('global');
const rows = staticData.rows || [];
staticData.rows = []; // reset for next run
return rows.map(r => ({ json: r }));

// Always summarize from Drain Collector's output (the full row set), regardless of which branch led here.
const rows = $('Drain Collector').all().map(i => i.json);
const dryRun = $('Config (toggle dry_run)').first().json.dry_run;
const byAccountKind = {};
const kindTotals = {};
for (const r of rows) {
  byAccountKind[r.account_id] = byAccountKind[r.account_id] || {};
  byAccountKind[r.account_id][r.kind] = (byAccountKind[r.account_id][r.kind] || 0) + 1;
  kindTotals[r.kind] = (kindTotals[r.kind] || 0) + 1;
}
const samplesByKind = {};
for (const r of rows) {
  if (!samplesByKind[r.kind]) samplesByKind[r.kind] = [];
  if (samplesByKind[r.kind].length < 5) samplesByKind[r.kind].push({
    account_id: r.account_id, audience_id: r.audience_id, name: r.name,
    custom_location_count: r.custom_location_count, has_excluded_geo: r.has_excluded_geo
  });
}
return [{ json: { mode: dryRun ? 'dry_run' : 'persisted', total_rows: rows.length, kind_totals: kindTotals, by_account_kind: byAccountKind, samples_by_kind: samplesByKind } }];

const items = $input.all();
const body = items.map(i => ({ ...i.json, last_seen: new Date().toISOString() }));
return [{ json: { rows: body, count: body.length } }];
